import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
const study='/tmp/engine-strike-columns-20261104';
const old=await import(study+'/reference/scripts/lib/strike_impact.ts');
const now=await import(study+'/candidate/scripts/lib/strike_impact.ts');
const oldGain=await import(study+'/reference/scripts/lib/contact_impact.ts');
const nowGain=await import(study+'/candidate/scripts/lib/contact_impact.ts');
let seed=0x425294f1,cases=0;
function random(){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return (seed>>>0)/2**32;}
const signed=()=>random()*40-20;
function eq(a:any,b:any){assert.deepEqual(a,b);cases++;}
function outcome(f:()=>any){try{return {value:f()};}catch(e){return {error:(e as Error).message};}}
const contracts=[old.STRIKE_CONTRACT,old.STRIKE_V2_CONTRACT,old.STRIKE_V3_CONTRACT];
for(let trial=0;trial<1000;trial++){
 const n=Math.floor(random()*80),first=Math.floor(random()*300),contact=Array.from({length:n},()=>random()<.7);
 const motions=Array.from({length:n},()=>({v:{x:signed(),y:signed()},L:signed()*100,R:random()*10+.01}));
 const data=Float64Array.from(motions.flatMap((m,i)=>[m.v.x,m.v.y,m.L,m.R,+contact[i]]));
 for(const c of contracts){
  const before=old.observeMotionWindow(first,data,c),after=now.observeMotionWindow(first,data,c);
  eq(after.toJSON(),before);
  eq(now.observeMotion(first,motions,f=>contact[f-first+1],c).toJSON(),old.observeMotion(first,motions,f=>contact[f-first+1],c));
  eq(now.observeStrikes(first,motions.map(m=>m.v),f=>contact[f-first+1],c).toJSON(),old.observeStrikes(first,motions.map(m=>m.v),f=>contact[f-first+1],c));
  const oldReversal:any[]=[],newReversal:any[]=[];
  eq(now.detectStrikes(after,c,(a:any,b:any)=>newReversal.push([a,b])),old.detectStrikes(before,c,(a:any,b:any)=>oldReversal.push([a,b])));eq(newReversal,oldReversal);
  eq(nowGain.contactSpeedGains(after),oldGain.contactSpeedGains(before));
  const duration=first+Math.floor(random()*(n+3))-1;
  eq(after.through(duration).toJSON(),before.filter((f:any)=>f.frame<=duration));
  const targets=Array.from({length:Math.floor(random()*4)},(_,k)=>({frame:first+k*12,impact:random()}));
  eq(now.evaluateStrikes(after,targets,duration,true,c),old.evaluateStrikes(before,targets,duration,true,c));
  for(const cut of new Set([0,n>>1,Math.max(0,n-1)])){
   const a=old.strikePrefix(before.slice(0,cut),c),b=now.strikePrefix(after.slice(0,cut),c);
   eq({through:b.through,events:b.events,pending:b.pending.toJSON()},a);
   eq(outcome(()=>now.continueStrikes(b,after.slice(cut),c)),outcome(()=>old.continueStrikes(a,before.slice(cut),c)));
  }
 }
}
// Keep the partial-impulse and discontinuity error behavior, including unused air rows.
for(let trial=0;trial<100;trial++){
 const frames=Array.from({length:12},(_,i)=>({frame:100+i,contact:random()<.7,J:random()*3,bend:random(),solverGain:signed(),gravityGain:signed(),speedBefore:random()*9,
  ...(random()<.85?{impulse:[signed(),signed(),signed()] as const}:{})}));
 if(trial%3===0)frames[6].frame++;
 const columns=now.StrikeFrames.fromFrames(frames);
 eq(columns.toJSON(),frames);
 for(const c of contracts)eq(outcome(()=>now.detectStrikes(columns,c)),outcome(()=>old.detectStrikes(frames,c)));
}
for(const x of [0,-0,Number.MIN_VALUE,-Number.MIN_VALUE,1e-200,-1e-200,1e200,-1e200,Number.MAX_VALUE,-Number.MAX_VALUE,Infinity,-Infinity,NaN]){
 for(const c of contracts){
  const d=Float64Array.from([x,-0,2,0,0,-0,x,-3,0,1,1,1,0,1,1]);
  eq(outcome(()=>now.observeMotionWindow(1,d,c).toJSON()),outcome(()=>old.observeMotionWindow(1,d,c)));
 }
}
writeFileSync(study+'/comparison.json',JSON.stringify({status:'PASS',cases,trajectories:1000,contracts:contracts.map(c=>c.id),description:'Exact observed fields, scalar/packed paths, events, reversal callbacks, accounts, gains, prefixes, continuations, errors and binary64 edge values against frozen reference.'},null,2)+'\n');console.log({cases});

