/** Owned numeric strike observations. Slices share read-only columns; concatenation
 * owns a fresh buffer. Populate a batch before handing it to an account/detector. */
export type StrikeFrame = {frame: number; contact: boolean; J: number; bend: number;
  impulse?: readonly [number, number, number];
  solverGain: number; gravityGain: number; speedBefore: number};

export class StrikeFrames {
  readonly frame: Float64Array;
  readonly contact: Float64Array;
  readonly J: Float64Array;
  readonly bend: Float64Array;
  readonly solverGain: Float64Array;
  readonly gravityGain: Float64Array;
  readonly speedBefore: Float64Array;
  readonly impulseX: Float64Array;
  readonly impulseY: Float64Array;
  readonly impulseSpin: Float64Array;
  readonly hasImpulse: Float64Array;
  private readonly columns: Float64Array[];

  constructor(readonly length: number, columns?: Float64Array[]) {
    const data = columns ? undefined : new Float64Array(length * 11);
    this.columns = columns ?? Array.from({length: 11}, (_, i) => data!.subarray(i * length, (i + 1) * length));
    [this.frame, this.contact, this.J, this.bend, this.solverGain, this.gravityGain, this.speedBefore,
      this.impulseX, this.impulseY, this.impulseSpin, this.hasImpulse] = this.columns;
  }

  slice(start = 0, end = this.length): StrikeFrames {
    const columns = this.columns.map(c => c.subarray(start, end));
    return new StrikeFrames(columns[0].length, columns);
  }

  concat(tail: StrikeFrames): StrikeFrames {
    if (!this.length) return tail;
    if (!tail.length) return this;
    const result = new StrikeFrames(this.length + tail.length);
    for (let i = 0; i < this.columns.length; i++) {
      result.columns[i].set(this.columns[i]);
      result.columns[i].set(tail.columns[i], this.length);
    }
    return result;
  }

  through(duration: number): StrikeFrames {
    let end = 0;
    while (end < this.length && this.frame[end] <= duration) end++;
    return this.slice(0, end);
  }

  /** Record adapters are for authored probes, research diagnostics and parity
   * serialization. Runtime observation and detection use the columns directly. */
  static fromFrames(frames: readonly StrikeFrame[]): StrikeFrames {
    const result = new StrikeFrames(frames.length);
    for (let i = 0; i < frames.length; i++) {
      const f = frames[i];
      result.frame[i] = f.frame; result.contact[i] = +f.contact;
      result.J[i] = f.J; result.bend[i] = f.bend;
      result.solverGain[i] = f.solverGain; result.gravityGain[i] = f.gravityGain; result.speedBefore[i] = f.speedBefore;
      if (f.impulse) {
        result.hasImpulse[i] = 1;
        result.impulseX[i] = f.impulse[0]; result.impulseY[i] = f.impulse[1]; result.impulseSpin[i] = f.impulse[2];
      }
    }
    return result;
  }

  toJSON(): StrikeFrame[] {
    return Array.from({length: this.length}, (_, i) => ({frame: this.frame[i], contact: !!this.contact[i], J: this.J[i], bend: this.bend[i],
      solverGain: this.solverGain[i], gravityGain: this.gravityGain[i], speedBefore: this.speedBefore[i],
      ...(this.hasImpulse[i] ? {impulse: [this.impulseX[i], this.impulseY[i], this.impulseSpin[i]] as const} : {})}));
  }
}

