import {expect, it} from 'vitest';
import {StrikeFrames, observeMotionWindow, STRIKE_V3_CONTRACT} from '../scripts/lib/strike_impact.ts';

it('owns packed observations after the borrowed native window changes', () => {
  const data = Float64Array.from([1, 2, 3, 4, 0, 5, 6, 7, 8, 1]);
  const frames = observeMotionWindow(1, data, STRIKE_V3_CONTRACT), saved = frames.toJSON();
  data.fill(999);
  expect(frames.toJSON()).toEqual(saved);
});

it('preserves signed zeros and missing impulses through record adapters', () => {
  const rows = [{frame: 0, contact: false, J: -0, bend: 0, solverGain: -0, gravityGain: 0, speedBefore: -0},
    {frame: 1, contact: true, J: 0, bend: -0, solverGain: 0, gravityGain: -0, speedBefore: 0, impulse: [-0, 0, -0] as const}];
  const frames = StrikeFrames.fromFrames(rows);
  expect(frames.toJSON()).toEqual(rows);
  expect(Object.is(frames.J[0], -0)).toBe(true);
  expect('impulse' in frames.toJSON()[0]).toBe(false);
  const serialized = frames.toJSON(); serialized[0].J = 42;
  expect(Object.is(frames.J[0], -0)).toBe(true);
});

it('slices include matching columns and concatenation owns the joined values', () => {
  const frames = StrikeFrames.fromFrames(Array.from({length: 5}, (_, i) => ({frame: i, contact: i % 2 === 1,
    J: i, bend: i + 1, solverGain: i + 2, gravityGain: i + 3, speedBefore: i + 4, impulse: [i + 5, i + 6, i + 7] as const})));
  const joined = frames.slice(0, 2).concat(frames.slice(2));
  expect(joined.toJSON()).toEqual(frames.toJSON());
  expect(frames.slice(-2).toJSON()).toEqual(frames.toJSON().slice(-2));
  expect(frames.through(2.5).toJSON()).toEqual(frames.toJSON().slice(0, 3));
  frames.J[0] = -99;
  expect(joined.J[0]).toBe(0);
  expect(new StrikeFrames(0).concat(joined).toJSON()).toEqual(joined.toJSON());
});

