import {it, expect} from 'vitest';
import {compileHandoff} from '../scripts/v0/optimizer/handoff.ts';
import {impactAccount} from '../scripts/v0/optimizer/impact_accounts.ts';
import {STRIKE_CONTRACT, STRIKE_V2_CONTRACT, STRIKE_V3_CONTRACT, StrikeFrames} from '../scripts/lib/strike_impact.ts';
import {createArcEngine} from '../scripts/v0/optimizer/arc_engine.ts';
import {extractRawTrajectory} from '../scripts/lib/detector.ts';
import {motionChanges} from '../tools/measure/motion_change.ts';
import {POINTS} from '../tools/measure/observe.ts';
import type {Spec} from '../scripts/v0/types.ts';

const spec: Spec = {duration: 3, preroll: 5, contacts: [.6, 1.2, 1.8, 2.4, 3].map(t => ({t, impact: .4})), axes: {air: () => .5, speed: () => .5}};

it('v2 sees nothing in free flight', () => {
  const engine = createArcEngine({position: {x: 0, y: 0}, velocity: {x: 5, y: -4}}, []), raw = extractRawTrajectory(engine, 30);
  const v2 = impactAccount(STRIKE_V2_CONTRACT.id), observed = v2.observe(engine, raw.frames);
  expect(v2.evaluate(observed, [], 30, true).events).toEqual([]);
  for (const f of observed.toJSON()) expect(Math.hypot(...f.impulse as [number, number, number])).toBeLessThan(.3);
});

it('v2 strengths equal the research measure the owner judged, with v1 events and timing', () => {
  const track = compileHandoff(spec, 101, {budget: 180000, creative: {}, impactContract: STRIKE_V2_CONTRACT.id}).track;
  const engine = createArcEngine({position: track.startPosition, velocity: track.riders[0].startVelocity}, track.lines);
  const raw = extractRawTrajectory(engine, 140);
  const v1 = impactAccount(STRIKE_CONTRACT.id), v2 = impactAccount(STRIKE_V2_CONTRACT.id);
  const e1 = v1.evaluate(v1.observe(engine, raw.frames), [], 140, true).events, e2 = v2.evaluate(v2.observe(engine, raw.frames), [], 140, true).events;
  expect(e2.length).toBeGreaterThan(2);
  expect(e2.map(e => [e.onset, e.end, e.peakFrame])).toEqual(e1.map(e => [e.onset, e.end, e.peakFrame]));
  // The research tool reads the same rider states as recorded observations.
  const frames = raw.frames.map(f => ({points: POINTS.map(id => {const p = (engine.getRider(f.frame).ballisticState().points as any)[id]; return [p.x, p.y, p.prevX, p.prevY];})}));
  const research = motionChanges({frames, observed: raw.frames.map(f => [engine.hasContactAtFrame(f.frame) ? 1 : 0])});
  expect(research.map(r => r.onset)).toEqual(e2.map(e => e.onset));
  for (const [i, r] of research.entries()) expect(e2[i].strength).toBeCloseTo(Math.min(1, r.strength), 9);
});

it('v3 separates opposite pushes (floor then upper rail) and leaves a single push alone', async () => {
  const {detectStrikes, STRIKE_V3_CONTRACT: V3, STRIKE_V2_CONTRACT: V2} = await import('../scripts/lib/strike_impact.ts');
  const frame = (f: number, contact: boolean, push: [number, number]) => ({frame: f, contact, J: Math.hypot(...push), bend: 0, solverGain: 0, gravityGain: 0,
    speedBefore: 0, impulse: [push[0], push[1], 0] as const});
  const air = (f: number) => frame(f, false, [0, 0]);
  // Floor push up (−y), then 2 frames later an upper rail pushing down (+y), all in one contact run.
  const bounce = StrikeFrames.fromFrames([air(0), frame(1, true, [0, -2]), frame(2, true, [0, -.3]), frame(3, true, [.2, 1.6]), frame(4, true, [0, .2]), air(5)]);
  expect(detectStrikes(bounce, V2)).toHaveLength(1);
  const e = detectStrikes(bounce, V3);
  expect(e).toHaveLength(2); expect(e[1].contactStart).toBe(3); expect(e[0].strength).toBeCloseTo(2.3 / 7.55, 6);
  // A corner (push turns 90°) stays one impact.
  const corner = StrikeFrames.fromFrames([air(0), frame(1, true, [0, -2]), frame(2, true, [-1.8, 0]), air(3)]);
  expect(detectStrikes(corner, V3)).toHaveLength(1);
});

it('v2/v3 incremental detection equals cold detection, across an opposite-push split', async () => {
  const {detectStrikes, strikePrefix, continueStrikes, STRIKE_V2_CONTRACT: V2, STRIKE_V3_CONTRACT: V3} = await import('../scripts/lib/strike_impact.ts');
  const frame = (f: number, contact: boolean, push: [number, number], spin = 0) => ({frame: f, contact, J: Math.hypot(...push), bend: .1, solverGain: 0, gravityGain: 0,
    speedBefore: 5, impulse: [push[0], push[1], spin] as const});
  const pushes: Array<[number, number] | null> = [null, null, [0, -2], [0, -.3], [.2, 1.6], [0, .2], null, null, [.5, -1.2], [.1, -.9], [0, -.2], null, [-1, 1.5], [0, -2.2], null];
  const all = StrikeFrames.fromFrames(pushes.map((p, f) => frame(f, !!p, p ?? [0, 0], f % 3 === 0 ? .3 : 0)));
  for (const c of [V2, V3]) {
    const cold = detectStrikes(all, c);
    for (let cut = 1; cut < all.length; cut++) expect(continueStrikes(strikePrefix(all.slice(0, cut), c), all.slice(cut), c)).toEqual(cold);
  }
  expect(detectStrikes(all, V3).length).toBeGreaterThan(detectStrikes(all, V2).length);
});

it('the native whole-body read equals bodyMotion over ballisticState exactly', async () => {
  const {bodyMotion} = await import('../scripts/lib/strike_impact.ts');
  const track = compileHandoff(spec, 101, {budget: 180000, creative: {}, impactContract: STRIKE_V3_CONTRACT.id}).track;
  const engine = createArcEngine({position: track.startPosition, velocity: track.riders[0].startVelocity}, track.lines);
  extractRawTrajectory(engine, 120);
  for (let f = 0; f <= 120; f++) expect((engine as any).bodyMotionAt(f)).toEqual(bodyMotion(engine.getRider(f).ballisticState()));
});

